INSERT INTO `f7i9_categories` (`id`, `category_name`, `category_alias`, `description`, `image`, `meta_tag`, `meta_keywords`, `meta_description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Women\'s Collection', 'womens-collection', '<p>Step into the world of bohemian fashion with our curated collection of women&rsquo;s boho clothing, designed for the free-spirited, creative soul. Embrace flowing silhouettes, vibrant prints, and earthy tones that capture the essence of effortless elegance. Our boho-chic styles feature airy maxi dresses, floral tops, layered skirts, and cozy kimonos, crafted from soft, breathable fabrics like cotton, linen, and lace. Each piece is adorned with unique details&mdash;think tassels, embroidery, and vintage-inspired patterns&mdash;to reflect your individuality and adventurous spirit. Perfect for festivals, beach days, or casual outings, our collection blends comfort and style, allowing you to mix, match, and layer to create your signature look. Complete your wardrobe with our boho accessories, from bold jewelry to fringed bags, and live the carefree, artistic lifestyle you love</p>\r\n', 'category-1.png', 'boho women\'s clothing, bohemian fashion, boho chic dresses, floral tops, maxi skirts, vintage-inspired clothing, boho accessories, free-spirited style, women\'s boho wear, festival fashion', 'Discover our boho women\'s wear collection featuring flowing maxi dresses, floral tops, and vintage-inspired styles. Shop bohemian fashion for a free-spirited, effortless look.', 'Discover our boho women\'s wear collection with flowing maxi dresses, floral tops, and vintage-inspired styles. Shop bohemian fashion for a free-spirited, effortless look.', 'Active', '2025-06-24 13:31:59', '2025-07-06 15:13:59'),
(2, 'Men\'s Collection', 'mens-collection', '<ul>\r\n	<li><strong>Men&#39;s Collection</strong></li>\r\n</ul>\r\n', 'art-silk-collection.png', 'Men\'s Collection', 'Men\'s Collection', 'Men\'s Collection', 'Active', '2025-07-04 15:01:50', '2025-07-06 15:27:27'),
(3, 'Accessories', 'accessories', '<p>Accessories</p>\r\n', 'accessories.png', 'Accessories', 'Accessories', 'Accessories', 'Active', '2025-07-06 15:28:52', '2025-07-13 10:36:21');
