INSERT INTO `f7i9_sliders` (`id`, `slide_name`, `image`, `status`) VALUES
(1, 'Slide 1', 'slide-1.webp', 'Active'),
(2, 'Slide 2', 'slide-2.webp', 'Active');
INSERT INTO `f7i9_subcategories` (`id`, `subcategory_name`, `subcategory_alias`, `cat_id`, `description`, `image`, `meta_tag`, `meta_keywords`, `meta_description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Long Dresses', 'long-dresses', 1, '<p><strong>Long Dresses</strong><br />\r\nDiscover elegance and versatility with our stunning collection of Long Dresses. Perfect for any occasion&mdash;from casual outings to glamorous events&mdash;our dresses come in a variety of styles, including Long Sleeves, Short Sleeves, and Sleeveless designs. Crafted from luxurious fabrics like cotton, silk, and rayon, with select pieces featuring exquisite foil detailing, these dresses offer timeless sophistication and comfort. Explore vibrant colors, flattering fits, and sizes ranging from XS to Plus Size to find your perfect look.</p>\r\n', 'sub-category-1.webp', 'COTTON SHORT DRESS', 'COTTON SHORT DRESS', 'COTTON SHORT DRESS', 'Active', '2025-06-24 13:55:00', '2025-07-06 15:15:53'),
(2, 'Short Dresses', 'short-dresses', 1, '<p>A <strong>cotton long boho dress</strong> is a flowing, maxi-length dress crafted from lightweight, breathable 100% cotton fabric, embodying the bohemian aesthetic with its relaxed, carefree vibe. These dresses typically feature vibrant floral, paisley, or tribal prints, intricate embroidery, or tie-dye patterns, often with details like ruffled hems, smocked bodices, tassels, or lace accents. Common design elements include V-necklines, 3/4 or long sleeves, tiered skirts, and elastic or drawstring waistbands for a flattering, A-line silhouette that suits various body types. Ideal for summer, festivals, beach outings, or casual gatherings, these dresses offer comfort and style, often paired with accessories like wide-brimmed hats, layered necklaces, or ankle boots for a complete boho look.</p>\r\n\r\n<p><strong>Manufacturers and Exporters in India</strong>: Several Indian companies specialize in manufacturing and exporting boho cotton dresses, offering handmade, sustainable, and customizable options:</p>\r\n\r\n<ul>\r\n	<li><strong>Mogul Interior (Florida, with production in India)</strong>: Produces eco-friendly boho dresses from recycled cotton and silks, featuring vibrant prints, asymmetrical designs, and embroidery. They cater to summer and fall wardrobes, emphasizing sustainable, handmade craftsmanship.</li>\r\n	<li><strong>Suppliers</strong>: Numerous verified exporters, primarily in Jaipur, New Delhi, and Ajmer, offer boho dresses like the &quot;Boho Breeze Yellow Maxi Dress&quot; (georgette with cotton lining, 48&quot; length) and custom layered dresses for designers and private labels. Locations include:\r\n	<ul>\r\n		<li>Jaipur (e.g., Kartarpura Industrial Area, Sanganer Bazar)</li>\r\n		<li>New Delhi (e.g., Patel Nagar, Sonia Vihar)</li>\r\n		<li>Pushkar, Ajmer (e.g., Ganahera, Parashar Colony)</li>\r\n		<li>Greater Noida, Ahmedabad, and Tiruppur also listed.</li>\r\n	</ul>\r\n	</li>\r\n</ul>\r\n', 'cotton-long-dress.png', 'cotton boho dress, bohemian maxi dress, handmade dresses, Indian dress exporter,', 'cotton boho dress, bohemian maxi dress, handmade dresses, Indian dress exporter,', '100% cotton boho maxi dresses with vibrant prints and embroidery. Perfect for summer and festivals. Wholesale and export from India.', 'Active', '2025-06-27 12:05:20', '2025-07-06 15:16:50'),
(3, 'Tops', 'tops', 1, '<p>Tops</p>\r\n', 'tops.jpg', 'Tops', 'Tops', 'Tops', 'Active', '2025-07-06 15:17:18', '2025-07-06 15:17:18'),
(4, 'Trousers', 'trousers', 1, '<p>Trousers</p>\r\n', 'trousers.jpg', 'Trousers', 'Trousers', 'Trousers', 'Active', '2025-07-06 15:18:22', '2025-07-06 15:18:22'),
(5, 'Skirts', 'skirts', 1, '<p>Skirts</p>\r\n', 'skirts.jpg', 'Skirts', 'Skirts', 'Skirts', 'Active', '2025-07-06 15:19:49', '2025-07-06 15:19:49'),
(6, 'Long & Short Kimonos', 'long-short-kimonos', 1, '<p>Long &amp; Short Kimonos</p>\r\n', 'long--short-kimonos.jpg', 'Long & Short Kimonos', 'Long & Short Kimonos', 'Long & Short Kimonos', 'Active', '2025-07-06 15:21:07', '2025-07-06 15:21:07'),
(7, 'Long & Short Mono (Jumpsuits) ', 'long-short-mono-jumpsuits', 1, '<p>Long &amp; Short Mono (Jumpsuits)&nbsp;</p>\r\n', 'long--short-mono-jumpsuits.jpg', 'Long & Short Mono (Jumpsuits) ', 'Long & Short Mono (Jumpsuits) ', 'Long & Short Mono (Jumpsuits) ', 'Active', '2025-07-06 15:23:24', '2025-07-06 15:23:24'),
